package com.gomgomapps.math.core;
import java.math.*;import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class NamibiaDecimalAddSubTest {
 @Test public void normalNaSixUsesUnlikePrecisionAndAllOperandCounts(){Generator g=new Generator(new Random(292));for(String id:List.of("decimalAdd","decimalSub")){var p=GlobalCurriculum.packs("NA").stream().filter(v->v.id.equals("na-nied-primary-2024-v1")).findFirst().orElseThrow();assertTrue(p.inGrade(id,6));var limits=GlobalCurriculum.limits(p.id,id,6);List<String> recent=new ArrayList<>();Set<Integer> arities=new HashSet<>(),precisions=new HashSet<>();for(int i=0;i<300;i++){Question q=g.next(id,recent,false,limits);assertFalse(recent.contains(q.signature()));recent.add(q.signature());List<String> original=DecimalAddSub.read(q);arities.add(original.size());Set<Integer> shown=new HashSet<>();BigDecimal expected=new BigDecimal(original.get(0));for(int j=0;j<original.size();j++){BigDecimal x=new BigDecimal(original.get(j));assertTrue(x.signum()>=0&&x.compareTo(new BigDecimal("100"))<0);shown.add(x.scale());precisions.add(x.scale());if(j>0)expected=id.equals("decimalAdd")?expected.add(x):expected.subtract(x);}assertTrue(shown.size()>1);assertTrue(expected.signum()>=0);q.answers[0]="poison";q.expression="poison";assertTrue(new Checker().check(q,List.of(),List.of(expected.toPlainString())).correct());assertFalse(HelpPlan.forQuestion(q).canTransfer());}assertEquals(Set.of(2,3,4),arities);assertEquals(Set.of(0,1,2,3),precisions);}}
 @Test public void originalFourOperandExampleAndPublicHelpSurvivePoisonedKeys(){Question q=DecimalAddSub.make("decimalAdd",List.of("25","6.27","0.8","4.125"));q.answers[0]="poison";q.expression="poison";assertTrue(new Checker().check(q,List.of(),List.of("36.195")).correct());assertFalse(new Checker().check(q,List.of(),List.of("36.185")).correct());HelpPlan h=HelpPlan.forQuestion(q);List<String> expected=List.of("25","6.27","0.8","4.125","3","1000","25000","6270","800","4125","31270","32070","36195","36.195");assertEquals(14,h.size());assertFalse(h.canTransfer());for(int i=0;i<expected.size();i++)assertTrue("frame "+i,h.step(i).accepts(expected.get(i)));}
 @Test public void zeroBorrowCarryAndMalformedOperandsAreIndependentOfAnswers(){Checker c=new Checker();for(String[] row:new String[][]{{"decimalAdd","99.999 + 0.001","100"},{"decimalSub","99.000 − 0.001 − 1.09 − 2","95.909"},{"decimalSub","0.00 − 0.000","0"},{"decimalAdd","0 + 0.00 + 0.000","0"}}){Question q=new Question(row[0],row[1],"poison","poison");assertTrue(c.check(q,List.of(),List.of(row[2])).correct());assertFalse(c.check(q,List.of(),List.of(new BigDecimal(row[2]).add(BigDecimal.ONE).toPlainString())).correct());assertFalse(HelpPlan.forQuestion(q).canTransfer());}for(String bad:List.of("1.2345678901234 + 2","1 + 2 × 3","1 + 2 + 3 + 4 + 5","1 + poison")){Question q=new Question("decimalAdd",bad,"1+2","3");assertEquals(Checker.Status.INPUT_NEEDED,c.check(q,List.of(),List.of("3")).status);}assertFalse(DecimalAddSub.selected("decimalAdd",GlobalCurriculum.limits("england-primary-2021-v1","decimalAdd",5)));}
}
